// #afb7da (a8206c81) — TC-API-01, TC-API-02. Guest API only: no device, no login, no POST, only ids 140/146 (no id enumeration).
import assert from 'node:assert/strict';
import { apiGet, USERS } from '../lib/session.js';

const PRIVATE = ['birthDate', 'street', 'email', 'favorites', 'exponentPushToken', 'verificationCodeDev'];
const IDS = [USERS.ios.id, USERS.android.id]; // 140, 146 — our test accounts

describe('Public user profile API (guest) #afb7da @api @android @ios @prod-safe', function () {
  this.timeout(60000);

  for (const id of IDS) {
    it(`TC-API-01: GET /user/${id} as guest — only public fields, push alias, rate-limit header`, async () => {
      const { status, headers, body } = await apiGet(`/user/${id}`);
      assert.equal(status, 200, `GET /user/${id} status`);
      assert.equal(String(body.id), String(id));
      for (const f of PRIVATE) assert.ok(!(f in body), `private field "${f}" must not be returned to a guest`);
      if ('fcmToken' in body && body.fcmToken !== null) {
        const tokens = Array.isArray(body.fcmToken) ? body.fcmToken : [body.fcmToken];
        for (const t of tokens) assert.equal(t, `user:${id}`, 'fcmToken may only be the "user:<id>" alias, never a real push token');
      }
      const limit = headers.get('x-ratelimit-limit-profile-ip');
      assert.ok(limit !== null, 'x-ratelimit-limit-profile-ip header must be present');
      assert.ok(Number(limit) > 0, `rate limit must be a positive number, got "${limit}"`);
    });
  }

  it('TC-API-02: GET /user (whole user list) as guest returns 404', async () => {
    const { status } = await apiGet('/user');
    assert.equal(status, 404);
  });
});
